def _unquote(token: str) -> str:
    token = token.strip()
    if len(token) >= 2 and token[0] in "'\"" and token[-1] == token[0]:
        return token[1:-1]
    return token


def _parse_filter_string(filter_string: str | None) -> list[_FilterClause]:
    if not filter_string or not filter_string.strip():
        return []

    clauses: list[_FilterClause] = []
    for raw_clause in _AND_SPLITTER.split(filter_string.strip()):
        clause = raw_clause.strip()
        if not clause:
            continue
        if m := re.match(r"^([\w.]+)\s+IN\s+\((.*)\)$", clause, re.IGNORECASE):
            values = [_unquote(v) for v in m.group(2).split(",") if v.strip()]
            clauses.append(_FilterClause(m.group(1), "IN", values))
        elif m := re.match(r"^([\w.]+)\s+(LIKE|ILIKE)\s+(.+)$", clause, re.IGNORECASE):
            clauses.append(
                _FilterClause(m.group(1), m.group(2).upper(), _unquote(m.group(3)))
            )
        elif m := re.match(r"^([\w.]+)\s*(!=|>=|<=|=|>|<)\s*(.+)$", clause):
            clauses.append(_FilterClause(m.group(1), m.group(2), _unquote(m.group(3))))
        else:
            raise MlflowException(
                f"Invalid filter clause: {clause!r}", error_code=INVALID_PARAMETER_VALUE
            )
    return clauses


def _like_to_regex(pattern: str) -> str:
    parts = []
    for ch in pattern:
        if ch == "%":
            parts.append(".*")
        elif ch == "_":
            parts.append(".")
        else:
            parts.append(re.escape(ch))
    return "^" + "".join(parts) + "$"


def _string_match(comparator: str, lhs: str | None, rhs: str) -> bool:
    if comparator in ("LIKE", "ILIKE"):
        flags = re.IGNORECASE if comparator == "ILIKE" else 0
        return re.match(_like_to_regex(rhs), lhs or "", flags) is not None
    if comparator in ("=", "!="):
        return _COMPARISON_OPERATORS[comparator](lhs, rhs)
    raise MlflowException(
        f"Invalid comparator {comparator!r} for string attribute",
        error_code=INVALID_PARAMETER_VALUE,
